#pragma once

#include "contrib/gpu/src/common/codec_decode_planning.hpp"

namespace openzl::gpu {

/**
 * Plans the stream regenerated by a fixed-width conversion.
 *
 * @p codec supplies the conversion transform identity and any staged width
 * header. @p inputs and @p outputs must each contain exactly one slot. The
 * output slot is unchanged on error.
 *
 * Byte-preserving conversions may alias their input; conversions that change
 * byte order require materialized output storage.
 *
 * This function validates and derives output properties only.
 *
 * @returns The regenerated output count, which is one, or an error.
 */
ZL_Report planConversionOutputs(
        const CodecDecodePlanningContext& codec,
        std::span<const StreamPlanningInput> inputs,
        std::span<CodecDecodeOutputPlan> outputs,
        ZL_OperationContext* opCtx);

} // namespace openzl::gpu
